using System;using System.Drawing;using System.Collections.Generic;using System.Diagnostics;using System.Linq;using System.Reflection;using System.Windows.Forms;using EmulatorHub;
class TextFieldTests {
 class PaintCounter:NativeWindow,IDisposable {public int Paints;public PaintCounter(Control c){AssignHandle(c.Handle);}protected override void WndProc(ref Message m){if(m.Msg==15)Paints++;base.WndProc(ref m);}public void Dispose(){ReleaseHandle();}}
 static void Pump(int ms){var w=Stopwatch.StartNew();while(w.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(3);}}
 static int checks;static void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}
 static void Verify(FishBowlDialog f){using(f){f.ShowInTaskbar=false;f.Show();Pump(300);var cp=(CreateParams)typeof(Control).GetProperty("CreateParams",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f,null);Check((cp.ExStyle&0x02000000)==0,"editor window must not composite native edit controls");foreach(var box in NextUi.Descendants(f).OfType<TextBoxBase>().Where(c=>c.Visible)){if(!box.ReadOnly)box.Text="Stable text field fixture";box.Select(2,5);box.Focus();Pump(150);var handle=box.Handle;var bounds=box.Bounds;var text=box.Text;int start=box.SelectionStart,length=box.SelectionLength;using(var counter=new PaintCounter(box)){Pump(1800);Check(counter.Paints<=2,"idle text field repeatedly repaints: "+counter.Paints);Check(box.Handle==handle&&box.Bounds==bounds,"idle text field recreates or moves");Check(box.Text==text&&box.SelectionStart==start&&box.SelectionLength==length,"idle text or selection changes");}if(!box.ReadOnly){box.SelectedText="replacement";Check(box.Text.Contains("replacement"),"native selection replacement failed");}}f.Close();}}
 static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Workspace(){var data=Store.Load();NextData.Ensure(data);LibraryAdditions.Ensure(data);data.Games.Clear();data.Emulators.Clear();Store.Save(data);using(var f=new MainForm(true)){f.ShowInTaskbar=false;f.Show();Pump(300);var tabs=(TabControl)Field(f,"workspaceNavigation");Check(tabs.DrawMode==TabDrawMode.OwnerDrawFixed&&((FishBowlTabs)tabs).LegacyHeaders,"workspace captions do not use the restored 1.12 appearance");var updateInfo=typeof(MainForm).GetMethod("UpdateInformationPanel",BindingFlags.Instance|BindingFlags.NonPublic);var emHome=(Control)Field(f,"emulatorHome");var children=NextUi.Descendants(emHome).ToArray();for(int i=0;i<8;i++)updateInfo.Invoke(f,null);Check(children.SequenceEqual(NextUi.Descendants(emHome)),"unselected emulator actions rebuild placeholder controls");var home=Field(f,"homeSurface");var library=(GameLibraryDialog)Field(f,"embeddedLibrary");var keys=typeof(MainForm).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.DeclaredOnly);
 var settings=(LibraryData)Field(f,"library");foreach(string command in new[]{"Home","Library","Emulators"}){Keys key=(Keys)Enum.Parse(typeof(Keys),settings.Enhancements.Shortcuts[command]);keys.Invoke(f,new object[]{f,new KeyEventArgs(key)});Pump(100);var page=tabs.SelectedTab;var controls=NextUi.Descendants(page).ToArray();for(int i=0;i<8;i++)keys.Invoke(f,new object[]{f,new KeyEventArgs(key)});Check(controls.SequenceEqual(NextUi.Descendants(page)),"repeated section hotkey rebuilds controls: "+command);}
 Console.WriteLine("Verifying search cancellation");var beforeSearch=NextUi.Descendants(tabs.SelectedTab).ToArray();bool oneSearch=false;using(var timer=new Timer{Interval=50}){timer.Tick+=(a,b)=>{var dialogs=Application.OpenForms.OfType<GlobalSearchDialog>().ToArray();if(dialogs.Length==0)return;timer.Stop();try{oneSearch=dialogs.Length==1;if(oneSearch){f.OpenCommandSearch();oneSearch=Application.OpenForms.OfType<GlobalSearchDialog>().Count()==1;}}finally{foreach(var dialog in dialogs)dialog.Close();}};timer.Start();keys.Invoke(f,new object[]{f,new KeyEventArgs(Keys.Control|Keys.K)});}Pump(100);Check(oneSearch,"Ctrl+K opens duplicate search windows");Check(beforeSearch.SequenceEqual(NextUi.Descendants(tabs.SelectedTab)),"cancelled search rebuilds underlying section");
 foreach(int page in new[]{0,1,2}){tabs.SelectedIndex=page;Pump(250);foreach(var box in NextUi.Descendants(tabs.SelectedTab).OfType<TextBoxBase>().Where(c=>c.Visible)){var handle=box.Handle;var bounds=box.Bounds;string text=box.Text;int start=box.SelectionStart,length=box.SelectionLength;using(var counter=new PaintCounter(box)){var frame=NextUi.Descendants(f).OfType<AquariumFrame>().First();for(int i=0;i<30;i++){frame.LeftRail.Advance(.04);frame.RightRail.Advance(.04);Pump(10);}Check(counter.Paints<=2,"bubble animation repaints text field");Check(box.Handle==handle&&box.Bounds==bounds&&box.Text==text&&box.SelectionStart==start&&box.SelectionLength==length,"bubble animation changes text field");}}}settings.Emulators.Add(new EmulatorProfile{Id="pane-fixture",Name="Fixture emulator",Executable=Application.ExecutablePath});typeof(MainForm).GetMethod("RefreshHub",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,null);tabs.SelectedIndex=1;var list=(ListView)Field(f,"emulatorList");list.Items[0].Selected=true;Pump(100);var info=(Control)Field(f,"emulatorInformation");Check(info.Visible&&!emHome.Visible,"selected emulator overlaps dashboard and information");list.Items[0].Selected=false;Pump(100);Check(!info.Visible&&emHome.Visible,"cleared emulator overlaps dashboard and information");Check(NextUi.Descendants(f).OfType<ComboBox>().All(c=>c.DrawMode==DrawMode.Normal),"dropdown text uses custom painting");
 Console.WriteLine("Verifying full-screen restoration");var fullscreen=typeof(MainForm).GetMethod("ToggleFullScreen",BindingFlags.Instance|BindingFlags.NonPublic);var restored=f.Bounds;var retained=NextUi.Descendants(tabs.SelectedTab).ToArray();for(int cycle=0;cycle<3;cycle++){Console.WriteLine("Cycle "+cycle+": maximize "+f.Bounds+" minimum "+f.MinimumSize);f.WindowState=FormWindowState.Maximized;Pump(80);f.WindowState=FormWindowState.Normal;Pump(80);fullscreen.Invoke(f,null);Pump(80);fullscreen.Invoke(f,null);Pump(100);Check(f.Bounds==restored&&retained.SequenceEqual(NextUi.Descendants(tabs.SelectedTab)),"full-screen restore changes bounds or recreates controls");var stable=retained.Select(c=>c.Bounds).ToArray();Pump(200);Check(stable.SequenceEqual(retained.Select(c=>c.Bounds)),"restored workspace keeps changing control sizes");}f.Close();}
 bool ran=false;Action selected;using(var search=new GlobalSearchDialog(new[]{new SearchResult{Caption="fixture action",Open=()=>ran=true}})){search.ShowInTaskbar=false;search.Show();Pump(50);typeof(GlobalSearchDialog).GetMethod("OpenSelected",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(search,null);Check(!ran&&!search.Visible,"search executes action before closing");selected=search.SelectedAction;Check(selected!=null,"search loses selected action");}selected();Check(ran,"closed search action fails");
 using(var parent=new Panel{Size=new Size(200,100)})using(var field=new TextBox{Bounds=new Rectangle(20,20,100,25)})using(var bitmap=new Bitmap(200,100)){parent.Controls.Add(field);using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(Color.Magenta);NativeSurfacePainting.ExcludeChildren(graphics,parent);graphics.FillRectangle(Brushes.Navy,parent.ClientRectangle);}Check(bitmap.GetPixel(30,30).ToArgb()==Color.Magenta.ToArgb(),"parent paints over native text field");Check(bitmap.GetPixel(0,0).ToArgb()==Color.Navy.ToArgb(),"parent exterior fails to paint");}
 }
 static void PressedText(){using(var button=new FishBowlActionButton{Text="Stationary words",Size=new Size(240,48),Font=new Font("Bahnschrift",12),BackColor=Color.Navy,ForeColor=Color.White})using(var before=new Bitmap(240,48))using(var after=new Bitmap(240,48)){var paint=typeof(FishBowlActionButton).GetMethod("OnPaint",BindingFlags.NonPublic|BindingFlags.Instance);using(var g=Graphics.FromImage(before))paint.Invoke(button,new object[]{new PaintEventArgs(g,new Rectangle(0,0,240,48))});typeof(FishBowlActionButton).GetMethod("OnMouseDown",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(button,new object[]{new MouseEventArgs(MouseButtons.Left,1,100,20,0)});using(var g=Graphics.FromImage(after))paint.Invoke(button,new object[]{new PaintEventArgs(g,new Rectangle(0,0,240,48))});int changed=0,white=0;for(int y=0;y<48;y++)for(int x=0;x<240;x++){bool a=before.GetPixel(x,y).ToArgb()==Color.White.ToArgb(),b=after.GetPixel(x,y).ToArgb()==Color.White.ToArgb();if(a)white++;if(a!=b)changed++;}Check(white>0,"button text fixture contains no lettering");Check(changed==0,"pressed button moves its lettering");}}
 static void PartialTextPaint(){using(var button=new FishBowlActionButton{Text="Stable text field",Size=new Size(240,48),Font=new Font("Bahnschrift",12),BackColor=Color.Navy,ForeColor=Color.White})using(var bitmap=new Bitmap(240,48)){using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(Color.Magenta);graphics.SetClip(new Rectangle(0,0,2,2));typeof(FishBowlActionButton).GetMethod("OnPaint",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(button,new object[]{new PaintEventArgs(graphics,new Rectangle(0,0,2,2))});}int outside=0;for(int y=0;y<48;y++)for(int x=0;x<240;x++)if((x>=2||y>=2)&&bitmap.GetPixel(x,y).ToArgb()!=Color.Magenta.ToArgb())outside++;Check(outside==0,"custom button text escapes partial repaint clip: "+outside);}
 using(var bitmap=new Bitmap(200,100))using(var graphics=Graphics.FromImage(bitmap))using(var font=new Font("Bahnschrift",12)){graphics.Clear(Color.Magenta);graphics.SetClip(new Rectangle(70,20,80,30));FishBowlText.DrawText(graphics,"Text must stay inside its field",font,new Rectangle(0,0,200,100),Color.White,TextFormatFlags.SingleLine);Check(Enumerable.Range(0,200).All(x=>Enumerable.Range(0,100).All(y=>new Rectangle(70,20,80,30).Contains(x,y)||bitmap.GetPixel(x,y).ToArgb()==Color.Magenta.ToArgb())),"shared text painter ignores field clip");}
 }
 static void RepeatedMenuPaint(){using(var menu=new MenuStrip{BackColor=Color.Navy})using(var bitmap=new Bitmap(240,40)){var item=new ToolStripMenuItem("Selection fixture"){AutoSize=false,Size=new Size(240,40)};menu.Items.Add(item);item.Select();var renderer=new FishBowlMenuRenderer();using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(Color.Magenta);renderer.DrawMenuItemBackground(new ToolStripItemRenderEventArgs(graphics,item));var before=new Bitmap(bitmap);try{renderer.DrawMenuItemBackground(new ToolStripItemRenderEventArgs(graphics,item));Check(Enumerable.Range(0,240).All(x=>Enumerable.Range(0,40).All(y=>before.GetPixel(x,y)==bitmap.GetPixel(x,y))),"selected menu changes pixels on repeated identical repaint");}finally{before.Dispose();}}}}
 [STAThread]static int Main(string[] args){try{if(args.Contains("--compact"))TextFit.WorkingAreaOverride=new Rectangle(0,0,1024,720);Application.EnableVisualStyles();Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Console.WriteLine("Verifying text prompt");Verify(new TextPromptDialog("Text field","Enter text"));Console.WriteLine("Verifying update notes");Verify(new WhatsNewDialog("1.24"));Console.WriteLine("Verifying notification text");Verify(new ResultsDialog("FishBowl Notifications",new[]{"INFO  Fixture notice\nDetails remain readable while selected."}));Console.WriteLine("Verifying workspace text fields");Workspace();Console.WriteLine("Verifying text painters");PartialTextPaint();PressedText();RepeatedMenuPaint();Console.WriteLine("PASS: "+checks+" native text field checks covering idle repaint, selection, handles and editing.");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
